on app01 'systemctl cat metrics-exporter >/dev/null 2>&1' || fail "there's no metrics-exporter systemd unit yet"
on app01 'systemctl is-active -q metrics-exporter' || fail "the metrics-exporter service isn't running (check its status/logs)"
on app01 'systemctl is-enabled -q metrics-exporter' || fail "it's running but not enabled — it won't start on boot"
on app01 '[ "$(systemctl show -p User --value metrics-exporter)" = kestrel ]' || fail "the service isn't configured to run as the kestrel user"
on app01 'ps -o user= -p $(pgrep -f "[m]etrics-exporter" | tr "\n" ",")0 | sort -u | grep -qv kestrel' && fail "there's still a copy running as root (the old tmux one?)"
on app01 'case $(systemctl show -p Restart --value metrics-exporter) in on-failure|always|on-abnormal) true;; *) false;; esac' || fail "Restart= isn't set, it won't come back if it crashes"
on app01 'curl -fsS -m 3 localhost:9100 | grep -q kestrel_up' || fail "nothing answers on :9100"
on app01 'old=$(systemctl show -p MainPID --value metrics-exporter); kill -9 $old; for i in $(seq 20); do sleep 0.5; new=$(systemctl show -p MainPID --value metrics-exporter); [ "$new" != 0 ] && [ "$new" != "$old" ] && systemctl is-active -q metrics-exporter && exit 0; done; exit 1' || fail "I kill -9'd it to test and it didn't come back"
